// It first checks the given session ID, then falls back to checking all
// sessions. This handles the case where the original session ended and
// the user started a new Claude session.
func isSessionIdle(sessionID string) bool {
	// Fast path: check the specific session
	if sessionID != "" {
		state, err := strategy.LoadSessionState(sessionID)
		if err == nil && state != nil && state.Phase == session.PhaseIdle {
			return true
		}
	}

	// Slow path: check if any session in this worktree is idle
	// (covers session restart, multiple sessions, etc.)
	mostRecent := strategy.FindMostRecentSession()
	if mostRecent != "" && mostRecent != sessionID {
		state, err := strategy.LoadSessionState(mostRecent)
		if err == nil && state != nil && state.Phase == session.PhaseIdle {
			return true
		}
	}

	return false
}

